135	export class DocumentService {
136	  private persistence: PersistenceService;
137	
138	  constructor(persistence: PersistenceService) {
139	    this.persistence = persistence;
140	  }
141	
142	  /** List all imported documents. */
143	  listDocuments(): Document[] {
144	    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
145	    return docs ?? [];
146	  }
147	
148	  /** Import a file from the given path. */
149	  importDocument(filePath: string): Document {
150	    if (!fs.existsSync(filePath)) {
151	      throw new Error(`File not found: ${filePath}`);
152	    }
153	
154	    const filename = path.basename(filePath);
155	    const content = fs.readFileSync(filePath, 'utf-8');
156	    const stats = fs.statSync(filePath);
157	
158	    const doc: Document = {
159	      id: uuidv4(),
160	      title: filename.replace(/\.[^.]+$/, ''),
161	      filename,
162	      importedAt: new Date().toISOString(),
163	      size: stats.size,
164	      status: 'imported',
165	    };
166	
167	    // Copy file to data directory
168	    this.persistence.copyFileToDocuments(filePath, filename);
169	
170	    // Store content for indexing and viewing
171	    this.persistence.writeText(`content/${doc.id}.txt`, content);
172	
173	    // Update metadata
174	    const docs = this.listDocuments();
175	    docs.push(doc);
176	    this.persistence.writeJson(DOCUMENTS_META, docs);
177	
178	    return doc;
179	  }
180	
181	  /** Get a single document by ID. */
182	  getDocument(id: string): Document | null {
183	    const docs = this.listDocuments();
184	    return docs.find(d => d.id === id) ?? null;
185	  }
186	
187	  /** Get the text content of a document. */
188	  getDocumentContent(id: string): string | null {
189	    return this.persistence.readText(`content/${id}.txt`);
190	  }
191	
192	  /** Update a document's metadata. */
193	  updateDocument(id: string, updates: Partial<Document>): Document | null {
194	    const docs = this.listDocuments();
195	    const index = docs.findIndex(d => d.id === id);
196	    if (index === -1) return null;
197	
198	    docs[index] = { ...docs[index], ...updates };
199	    this.persistence.writeJson(DOCUMENTS_META, docs);
200	    return docs[index];
201	  }
202	
203	  /** Delete a document by ID. Removes content and metadata. */
204	  deleteDocument(id: string): boolean {
205	    const docs = this.listDocuments();
206	    const doc = docs.find(d => d.id === id);
207	    if (!doc) return false;
208	
209	    // Remove file from documents directory
210	    this.persistence.deleteFromDocuments(doc.filename);
211	
212	    // Remove stored content
213	    const contentPath = path.join(this.persistence.getDataDir(), 'content', `${id}.txt`);
214	    if (fs.existsSync(contentPath)) {
215	      fs.unlinkSync(contentPath);
216	    }
217	
218	    // Update metadata
219	    const updated = docs.filter(d => d.id !== id);
220	    this.persistence.writeJson(DOCUMENTS_META, updated);
221	    return true;
222	  }
223	
224	  /** Check whether the persistence layer has stored data. */
225	  hasPersistedData(): boolean {
226	    return this.persistence.exists(DOCUMENTS_META);
227	  }
228	}
