233	const INDEX_META = 'index-meta.json';
234	const CHUNKS_DIR = 'chunks';
235	
236	interface IndexStatus {
237	  status: 'idle' | 'indexing' | 'ready' | 'error';
238	  currentIndexed: number;
239	  totalDocuments: number;
240	  lastIndexed: string | null;
241	}
