243	export class IndexingService {
244	  private persistence: PersistenceService;
245	
246	  constructor(persistence: PersistenceService) {
247	    this.persistence = persistence;
248	  }
249	
250	  /** Start indexing documents. If documentId is provided, index only that document. */
251	  async startIndexing(documentId?: string): Promise<IndexStatus> {
252	    const status = this.getStatus();
253	
254	    if (documentId) {
255	      // Index a single document
256	      const content = this.persistence.readText(`content/${documentId}.txt`);
257	      if (!content) {
258	        return { ...status, status: 'error' };
259	      }
260	      const chunks = this.chunkDocument(documentId, content);
261	      this.persistence.writeJson(`${CHUNKS_DIR}/${documentId}.json`, chunks);
262	      return this.getStatus();
263	    }
264	
265	    // Index all documents that haven't been indexed yet
266	    const docsMeta = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
267	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
268	
269	    for (const doc of docsMeta) {
270	      if (chunksMeta[doc.id]) continue;
271	
272	      const content = this.persistence.readText(`content/${doc.id}.txt`);
273	      if (!content) continue;
274	
275	      const chunks = this.chunkDocument(doc.id, content);
276	      this.persistence.writeJson(`${CHUNKS_DIR}/${doc.id}.json`, chunks);
277	      chunksMeta[doc.id] = chunks.map(c => c.id);
278	    }
279	
280	    this.persistence.writeJson(INDEX_META, chunksMeta);
281	    return this.getStatus();
282	  }
283	
284	  /** Get current indexing status. */
285	  getStatus(): IndexStatus {
286	    const docs = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
287	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
288	
289	    const currentIndexed = Object.keys(chunksMeta).length;
290	    const totalDocuments = docs.length;
291	    const isReady = currentIndexed === totalDocuments && totalDocuments > 0;
292	
293	    return {
294	      status: isReady ? 'ready' : currentIndexed > 0 ? 'indexing' : 'idle',
295	      currentIndexed,
296	      totalDocuments,
297	      lastIndexed: new Date().toISOString(),
298	    };
299	  }
300	
301	  /** Get all chunks for a document. */
302	  getChunksForDocument(documentId: string): Chunk[] {
303	    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
304	  }
305	
306	  /** Get all chunks across all documents. */
307	  getAllChunks(): Chunk[] {
308	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
309	    const allChunks: Chunk[] = [];
310	
311	    for (const docId of Object.keys(chunksMeta)) {
312	      const chunks = this.getChunksForDocument(docId);
313	      allChunks.push(...chunks);
314	    }
315	
316	    return allChunks;
317	  }
318	
319	  /** Split a document into chunks of ~500 characters at paragraph boundaries. */
320	  private chunkDocument(documentId: string, content: string): Chunk[] {
321	    const CHUNK_SIZE = 500;
322	    const chunks: Chunk[] = [];
323	
324	    // Split on double newlines (paragraphs)
325	    const paragraphs = content.split(/\n\s*\n/).filter(p => p.trim().length > 0);
326	
327	    let buffer = '';
328	    let chunkIndex = 0;
329	
330	    for (const para of paragraphs) {
331	      if (buffer.length + para.length > CHUNK_SIZE && buffer.length > 0) {
332	        chunks.push(this.createChunk(documentId, chunkIndex++, buffer.trim()));
333	        buffer = para;
334	      } else {
335	        buffer += (buffer ? '\n\n' : '') + para;
336	      }
337	    }
338	
339	    if (buffer.trim()) {
340	      chunks.push(this.createChunk(documentId, chunkIndex, buffer.trim()));
341	    }
342	
343	    return chunks;
344	  }
345	
346	  private createChunk(documentId: string, index: number, content: string): Chunk {
347	    return {
348	      id: uuidv4(),
349	      documentId,
350	      content,
351	      index,
352	      metadata: {
353	        charCount: String(content.length),
354	        wordCount: String(content.split(/\s+/).length),
355	      },
356	    };
357	  }
358	}
