362	export class PersistenceService {
363	  private dataDir: string;
364	  private documentsDir: string;
365	  private indexDir: string;
366	
367	  constructor(dataDir: string) {
368	    this.dataDir = dataDir;
369	    this.documentsDir = path.join(dataDir, 'documents');
370	    this.indexDir = path.join(dataDir, 'index');
371	    this.ensureDirectories();
372	  }
373	
374	  private ensureDirectories() {
375	    fs.mkdirSync(this.dataDir, { recursive: true });
376	    fs.mkdirSync(this.documentsDir, { recursive: true });
377	    fs.mkdirSync(this.indexDir, { recursive: true });
378	  }
379	
380	  /** Read a JSON file, returning null if it doesn't exist. */
381	  readJson<T>(relativePath: string): T | null {
382	    const fullPath = path.join(this.dataDir, relativePath);
383	    if (!fs.existsSync(fullPath)) return null;
384	    return JSON.parse(fs.readFileSync(fullPath, 'utf-8'));
385	  }
386	
387	  /** Write a JSON file atomically. */
388	  writeJson<T>(relativePath: string, data: T): void {
389	    const fullPath = path.join(this.dataDir, relativePath);
390	    const dir = path.dirname(fullPath);
391	    fs.mkdirSync(dir, { recursive: true });
392	    fs.writeFileSync(fullPath, JSON.stringify(data, null, 2), 'utf-8');
393	  }
394	
395	  /** Read a text file. */
396	  readText(relativePath: string): string | null {
397	    const fullPath = path.join(this.dataDir, relativePath);
398	    if (!fs.existsSync(fullPath)) return null;
399	    return fs.readFileSync(fullPath, 'utf-8');
400	  }
401	
402	  /** Write a text file. */
403	  writeText(relativePath: string, content: string): void {
404	    const fullPath = path.join(this.dataDir, relativePath);
405	    const dir = path.dirname(fullPath);
406	    fs.mkdirSync(dir, { recursive: true });
407	    fs.writeFileSync(fullPath, content, 'utf-8');
408	  }
409	
410	  /** Copy a file into the documents directory. */
411	  copyFileToDocuments(sourcePath: string, filename: string): string {
412	    const destPath = path.join(this.documentsDir, filename);
413	    fs.mkdirSync(this.documentsDir, { recursive: true });
414	    fs.copyFileSync(sourcePath, destPath);
415	    return destPath;
416	  }
417	
418	  /** Delete a file from the documents directory. */
419	  deleteFromDocuments(filename: string): void {
420	    const filePath = path.join(this.documentsDir, filename);
421	    if (fs.existsSync(filePath)) {
422	      fs.unlinkSync(filePath);
423	    }
424	  }
425	
426	  /** List all files in a directory. */
427	  listFiles(relativePath: string): string[] {
428	    const fullPath = path.join(this.dataDir, relativePath);
429	    if (!fs.existsSync(fullPath)) return [];
430	    return fs.readdirSync(fullPath);
431	  }
432	
433	  /** Check if a file exists. */
434	  exists(relativePath: string): boolean {
435	    return fs.existsSync(path.join(this.dataDir, relativePath));
436	  }
437	
438	  /** Get the data directory path. */
439	  getDataDir(): string {
440	    return this.dataDir;
441	  }
442	
443	  /** Get the documents directory path. */
444	  getDocumentsDir(): string {
445	    return this.documentsDir;
446	  }
447	
448	  /** Get the index directory path. */
449	  getIndexDir(): string {
450	    return this.indexDir;
451	  }
