460	const MOCK_PATTERNS: Array<{
461	  keywords: string[];
462	  answer: string;
463	  excerpt: string;
464	}> = [
465	  {
466	    keywords: ['design', 'architecture', 'pattern'],
467	    answer: 'The system uses a layered architecture with clear boundaries between the main process, preload scripts, and renderer. Each layer communicates through typed IPC channels, and the services layer handles business logic independently of the UI.',
468	    excerpt: 'The system uses a layered architecture with clear boundaries',
469	  },
470	  {
471	    keywords: ['import', 'document', 'file'],
472	    answer: 'Documents are imported by copying the source file to the local data directory. The system extracts text content and creates metadata including title, filename, size, and import timestamp. After import, documents can be indexed for search.',
473	    excerpt: 'Documents are imported by copying the source file',
474	  },
475	  {
476	    keywords: ['index', 'chunk', 'search'],
477	    answer: 'The indexing pipeline splits documents into chunks of approximately 500 characters at paragraph boundaries. Each chunk includes metadata like character count and word count. The index enables grounded Q&A with citations pointing to specific document sections.',
478	    excerpt: 'The indexing pipeline splits documents into chunks',
479	  },
480	  {
481	    keywords: ['retrieval', 'search', 'query'],
482	    answer: 'Retrieval works by matching query keywords against indexed chunks. The system ranks chunks by keyword overlap and returns the most relevant excerpts as citations alongside the generated answer.',
483	    excerpt: 'Retrieval works by matching query keywords against indexed chunks',
484	  },
485	  {
486	    keywords: ['meeting', 'notes', 'summary'],
487	    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
488	    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
489	  },
