492	export class QaService {
493	  private persistence: PersistenceService;
494	  private indexingService: IndexingService;
495	
496	  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
497	    this.persistence = persistence;
498	    this.indexingService = indexingService ?? new IndexingService(persistence);
499	  }
500	
501	  /** Ask a question and get a grounded answer with citations. */
502	  async ask(question: string): Promise<QAResponse> {
503	    // Simulate processing delay
504	    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));
505	
506	    const chunks = this.indexingService.getAllChunks();
507	    const citations: Citation[] = [];
508	
509	    if (chunks.length > 0) {
510	      // Find relevant chunks using keyword matching
511	      const questionWords = question.toLowerCase().split(/\s+/).filter(w => w.length > 2);
512	      const scored = chunks.map(chunk => {
513	        const contentLower = chunk.content.toLowerCase();
514	        const score = questionWords.reduce(
515	          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
516	          0
517	        );
518	        return { chunk, score };
519	      });
520	
521	      // Take top 2 relevant chunks as citations
522	      const relevant = scored
523	        .filter(s => s.score > 0)
524	        .sort((a, b) => b.score - a.score)
525	        .slice(0, 2);
526	
527	      // Get document metadata for citations
528	      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
529	
530	      for (const { chunk } of relevant) {
531	        const doc = docs.find(d => d.id === chunk.documentId);
532	        citations.push({
533	          documentId: chunk.documentId,
534	          documentTitle: doc?.title ?? 'Unknown Document',
535	          chunkIndex: chunk.index,
536	          excerpt: chunk.content.substring(0, 200),
537	        });
538	      }
539	    }
540	
541	    // Generate answer from mock patterns or use fallback
542	    const answer = this.generateAnswer(question, citations);
543	
544	    const response: QAResponse = {
545	      answer,
546	      citations,
547	      confidence: citations.length > 0 ? 0.85 : 0.3,
548	      timestamp: new Date().toISOString(),
549	    };
550	
551	    // Save to history
552	    this.saveToHistory(question, response);
553	
554	    return response;
555	  }
556	
557	  /** Get the Q&A history. */
558	  getHistory(): QAHistory[] {
559	    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
560	  }
561	
562	  private generateAnswer(question: string, citations: Citation[]): string {
563	    // Match against mock patterns
564	    const questionLower = question.toLowerCase();
565	    for (const pattern of MOCK_PATTERNS) {
566	      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
567	        if (citations.length > 0) {
568	          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
569	        }
570	        return pattern.answer;
571	      }
572	    }
573	
574	    // Fallback answer
575	    if (citations.length > 0) {
576	      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
577	    }
578	
579	    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
580	  }
581	
582	  private saveToHistory(question: string, response: QAResponse): void {
583	    const history = this.getHistory();
584	    history.push({ question, response });
585	    this.persistence.writeJson(QA_HISTORY_FILE, history);
586	  }
587	}
